// Generated by `npx neus specimen`: the active system's tokens and components, in light and dark.
// Run it again after changing the system, the derived system or the palette; delete it when done.
import {
  Alert, Avatar, AvatarGroup, Badge, Button, Card, CardContent, CardFooter, CardHeader, Checkbox, DateInput, Grid,
  Heading, Input, MediaPlaceholder, Section, Select, Stack, Text, ThemeProvider,
} from "neus-ui";
import type { ColorScheme, DesignSystemId, ThemeConfig } from "neus-ui";

const SYSTEM = "{{DESIGN_SYSTEM}}" as DesignSystemId;
const NAME = "{{NAME}}";
const COLORS: ThemeConfig = JSON.parse('{{COLORS}}');
const PALETTE = ["primary", "success", "error", "info", "warning"];
const SURFACES = ["surface", "surface-secondary", "text-primary", "text-secondary", "border-subtle"];
const VARIANTS = ["solid", "secondary", "tonal", "elevated", "outlined", "text"] as const;
const CARDS = ["auto", "filled", "outlined", "elevated"] as const;
const TONES = ["default", "subtle", "accent", "brand", "inverse"] as const;
const STATUSES = ["info", "success", "warning", "error"] as const;
const OPTIONS = [{ value: "a", label: "Option A" }, { value: "b", label: "Option B" }];

const Swatch = ({ token }: { token: string }) => (
  <Stack gap={2}>
    <Card variant="outlined" style={{ background: `var(--color-${token})`, minHeight: 56 }} />
    <Text variant="caption" tone="muted">--color-{token}</Text>
  </Stack>
);

const Panel = ({ scheme }: { scheme: ColorScheme }) => (
  <ThemeProvider scope="local" designSystem={SYSTEM} colorScheme={scheme} initialTheme={COLORS}>
    {/* The provider's wrapper has no box: the panel paints its own surface for each scheme. */}
    <Section spacing="md" container="xl" aria-label={`${NAME}, ${scheme}`}
      style={{ background: "var(--color-surface)", color: "var(--color-text-primary)" }}>
      <Stack gap={12}>
        <Stack gap={4}>
          <Text variant="overline" tone="primary">{NAME} · {scheme}</Text>
          <Heading as="h2" size="display">Display headline</Heading>
          <Heading as="h3" size="xl">Extra large heading</Heading>
          <Heading as="h3" size="lg">Large heading</Heading>
          <Heading as="h4" size="md">Medium heading</Heading>
          <Text variant="lead">Lead text introduces a page in one or two sentences.</Text>
          <Text>Body text carries the content: sixteen pixels or more, at a comfortable measure.</Text>
          <Text variant="small" tone="muted">Small muted text for notes and metadata.</Text>
        </Stack>
        <Grid columns={{ base: 2, md: 5 }} gap={4}>
          {[...PALETTE, ...SURFACES].map((token) => <Swatch key={token} token={token} />)}
        </Grid>
        <Stack gap={4}>
          {(["small", "medium", "large"] as const).map((size) => (
            <Stack key={size} direction="row" gap={3} wrap align="end">
              <Input label={`Field ${size}`} size={size} placeholder="Type here" wrapperStyle={{ maxWidth: 240 }} />
              {VARIANTS.map((variant) => <Button key={variant} label={variant} variant={variant} size={size} />)}
            </Stack>
          ))}
          <Stack direction="row" gap={3} wrap align="center">
            <Button label="Disabled" disabled />
            <Button label="Loading" loading />
            <Button label="Error" color="error" />
            {(["primary", "success", "error", "info", "neutral"] as const).map((color) => <Badge key={color} label={color} color={color} />)}
          </Stack>
        </Stack>
        <Grid columns={{ base: 1, md: 3 }} gap={6}>
          <Input label="Name" required description="As it appears on your ID." />
          <Select label="Plan" required options={OPTIONS} description="You can change it later." />
          <DateInput label="Start date" description="Any weekday." />
          <Input label="Email" error="Enter an email such as ana@example.com." defaultValue="ana@" />
          <Input label="Read only" readonly defaultValue="Locked value" description="Set by your administrator." />
          <Checkbox label="Send me the weekly summary" />
        </Grid>
        <Grid columns={{ base: 1, md: 2 }} gap={4}>
          {STATUSES.map((status) => <Alert key={status} status={status} title={`${status} title`}>An {status} message with its next step.</Alert>)}
        </Grid>
        <Grid as="ul" columns={{ base: 1, md: 2, lg: 4 }}>
          {CARDS.map((variant) => (
            <Card key={variant} as="li" variant={variant}>
              <CardHeader><Heading as="h4" size="sm">{variant} card</Heading></CardHeader>
              <CardContent><Text tone="muted">Content keeps the card's inset.</Text></CardContent>
              <CardFooter><Button label="Action" fullWidth /></CardFooter>
            </Card>
          ))}
        </Grid>
        <Stack direction="row" gap={6} align="center" wrap>
          <Avatar name="Ana Paz" size="large" />
          <AvatarGroup max={3}>
            {["Ana Paz", "Bruno Díaz", "Carla Gómez", "Diego Ruiz"].map((name) => <Avatar key={name} name={name} />)}
          </AvatarGroup>
          <MediaPlaceholder label="A picture of the product or the place" ratio="16 / 9" style={{ maxWidth: 320 }} />
        </Stack>
        <Stack gap={0}>
          {TONES.map((tone) => (
            <Section key={tone} tone={tone} spacing="sm" container={false}>
              <Stack direction="row" gap={4} align="center" justify="between" wrap style={{ paddingInline: 24 }}>
                <Text weight="semibold">Section tone {tone}</Text>
                <Button label="Primary action" />
              </Stack>
            </Section>
          ))}
        </Stack>
      </Stack>
    </Section>
  </ThemeProvider>
);

export const NeusSpecimen = () => (
  <>
    <Panel scheme="light" />
    <Panel scheme="dark" />
  </>
);
